int main(void) {
    int N;
    scanf("%d", &N);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int value = i + 1;
            if (j + 1 < value) value = j + 1;
            if (N - i < value) value = N - i;
